import{_ as l,a0 as o,w as r,s as d,ao as a,I as n,x as p,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"用 NMAP 探測操作系統 | LCTT x X-CMD","titleTemplate":false,"description":"用 NMAP 探測操作系統 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 NMAP 探測操作系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 NMAP 探測操作系統 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170529 NMAP OS Detection","title":"用 NMAP 探測操作系統","tag":"201707","desc":""},"relativePath":"201707/20170529 NMAP OS Detection.md","filePath":"[post].md"}'),g={name:"201707/20170529 NMAP OS Detection.md"};function u(h,s,m,P,c,b){const i=o("Link");return r(),d("div",null,[s[16]||(s[16]=a('<h1 id="用-nmap-探測操作系統" tabindex="-1">用 NMAP 探測操作系統 <a class="header-anchor" href="#用-nmap-探測操作系統" aria-label="Permalink to “用 NMAP 探測操作系統”">​</a></h1><p>有時，能夠知道一個網絡裏的機器的操作系統（OS）是有一定好處的。當你知道一台機器的操作系統後，因為你可以在網上搜索專門針對該系統的安全漏洞，所以入侵系統也會更加容易。當然，安全漏洞通常都會很快被修補，但安全漏洞存在時你需要知道。</p><p>對你自己的網絡進行掃描以便發現操作系統類型可以幫助你瞭解黑客將如何侵入你的網絡。</p><h3 id="操作系統探測資料庫" tabindex="-1">操作系統探測資料庫 <a class="header-anchor" href="#操作系統探測資料庫" aria-label="Permalink to “操作系統探測資料庫”">​</a></h3><p>NAMP 帶有一個數據庫，它在你安裝 NAMP 的時候就會被安裝。這個資料庫用於操作系統的探測，但是它不會自動更新。</p><p>這個資料庫位於 <code>/usr/share/nmap/nmap-os-db</code>。進行更新的最簡單方式是首先找到資料庫的版本號，用文本編輯器打開這個文件，版本號通常位於第二行。我的資料庫的第二行是 <code># $Id: nmap-os-db 35407 2015-11-10 04:26:26Z dmiller $</code>，即這個文件的資料庫版本是 35407。</p>',6)),n("p",null,[s[1]||(s[1]=p("要在網上查找一個可更新版本，可以瀏覽 ",-1)),t(i,{href:"https://svn.nmap.org/nmap%EF%BC%8C%E5%A6%82%E5%9C%96"},{default:e(()=>[...s[0]||(s[0]=[p("https://svn.nmap.org/nmap，如圖",-1)])]),_:1}),s[2]||(s[2]=p(" 1 所示：",-1))]),s[17]||(s[17]=a(`<p><img src="https://www.linux.org/attachments/figure-01-jpg.699/" alt="Figure 01.jpg"></p><p><em>圖 1</em></p><p>你可以從圖中看到版本號為 36736，與我的系統上的版本號相比，這個版本號似乎是一個更新的版本。為了對更新的操作系統進行準確的操作系統探測，當然需要對這個資料庫進行更新。</p><p>保留較舊的資料庫版本也是一個不錯的主意。我當前和版本是 35407，我將在終端執行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mv /usr/share/nmap/nmap-os-db /usr/share/nmap/nmap-os-db-35407</span></span></code></pre></div><p>這個資料庫被以包含版本號的方式重命名了，下一步就是從網站上下載新版本的資料庫，在終端執行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /usr/share/nmap</span></span>
<span class="line"><span>sudo su</span></span>
<span class="line"><span>wget   https://svn.nmap.org/nmap/nmap-os-db</span></span></code></pre></div><p>新的資料庫即將開始被下載，但是你應該加上版本號，就像你在圖 1 中看到的版本號 36736。使用文本編輯器打開這個資料庫，然後在第二行加上版本號。當版本號變化後，你可以更新你的資料庫，然後在其中加入版本號，以便在再次檢查更新時做好準備。</p><h3 id="系統探測過程" tabindex="-1">系統探測過程 <a class="header-anchor" href="#系統探測過程" aria-label="Permalink to “系統探測過程”">​</a></h3><p>在我們開始使用實際的命令並執行系統探測之前，我們應該詳細介紹掃描過程中將會發生的事情。</p><p>會執行五種不同的測試，每種測試由一個或者多個數據包組成，目標系統對每個數據包作出的響應有助於確定操作系統的類型。</p><p>五種不同的測試是：</p><ol><li>序列生成（Sequence Generation）</li><li>ICMP 回顯</li><li>TCP 顯式擁塞通知（Explicit Congestion Notification）</li><li>TCP</li><li>UDP</li></ol><p>現在讓我們分別看看他們各自在做什麼。</p><p><strong>序列生成</strong></p><p>序列生成測試由六個數據包組成，這六個包是每隔 100 毫秒分開發送的，且都是 TCP SYN 包。</p><p>每個 TCP SYN 包的結果將有助於 NMAP 確定操作系統的類型。</p><p><strong>ICMP 回顯</strong></p><p>兩個有着不同設置的 ICMP 請求包被送到目標系統，由此產生的反應將有助於實現驗證操作系統類型。</p><p><strong>TCP 顯式擁塞通知（Explicit Congestion Notification）</strong></p><p>當生成許多包通過路由器時會導致其負載變大，這稱之為擁塞。其結果就是系統會變慢以降低擁堵，以便路由器不會發生丟包。</p><p>這個包僅為了得到目標系統的響應而發送。因為不同的操作系統以不同的方式處理這個包，所以返回的特定值可以用來判斷操作系統。</p><p><strong>TCP</strong></p><p>在這個測試中會發送六個數據包。</p><p>一些帶有特定的包設置的包被髮送用來到打開的或關閉的端口。結果也將會因為操作系統的不同而不同。</p><p>所有 TCP 包都是以如下不同的標誌被髮送：</p><ol><li>無標誌</li><li>SYN、FIN、URG 和 PSH</li><li>ACK</li><li>SYN</li><li>ACK</li><li>FIN、PSH 和 URG</li></ol><p><strong>UDP</strong></p><p>這個測試由一個被髮送給一個關閉的端口的數據包組成。</p><p>如果目標系統上的這個端口是關閉的，而且返回一條 ICMP 端口不可達的信息，那麼就説明沒有防火牆。</p><h3 id="nmap-操作系統檢測命令" tabindex="-1">NMAP 操作系統檢測命令 <a class="header-anchor" href="#nmap-操作系統檢測命令" aria-label="Permalink to “NMAP 操作系統檢測命令”">​</a></h3><p>現在我們開始實際動手進行系統探測。如果你已經讀過一些我寫的關於 NMAP 的文章，那麼最好不要執行 PING 操作。為了跳過 PING，我們使用參數 <code>Pn</code>。為了看到詳細的信息，你應該使用 <code>-v</code> 參數用於動態顯示。為了獲取系統的信息，需要使用 <code>-O</code> 參數。</p><p>為了使命令順利運行和執行 TCP SYN 掃描，你需要以管理員的身份來執行這個命令。在我的例子中，我將只在一個系統上而不是整個網絡上進行掃描，使用的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nmap -v -Pn -O 192.168.0.63</span></span></code></pre></div><p>掃描的結果如圖2所示，掃描顯示七個開放的端口。</p><p><img src="https://www.linux.org/attachments/figure-02-jpg.700/" alt="Figure 02.jpg"></p><p><em>圖 2</em></p><p>開放的端口是：</p><ol><li>21/tcp ftp</li><li>22/tcp ssh</li><li>111/tcp rpcbind</li><li>139/tcp netbios-ssn</li><li>445/tcp microsoft-ds</li><li>2049/tcp nfs</li><li>54045/tcp unknown</li></ol><p>系統的 MAC 地址為為：<code>00:1E:4F:9F:DF:7F</code>。</p><p>後面部分顯示系統類型為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Device type: general purpose</span></span>
<span class="line"><span>Running: Linux 3.X|4.X</span></span>
<span class="line"><span>OS CPE: cpe:/o:linux:linux_kernel:3 cpe:/o:linux:linux_kernel:4</span></span>
<span class="line"><span>OS details: Linux 3.2 - 4.6</span></span>
<span class="line"><span>Uptime guess: 0.324 days (since Sun Apr 23 08:43:32 2017)</span></span></code></pre></div><p>系統當前運行的是 Ubuntu Server 16.04，Linux 內核為 4.8，運行時間猜的較準確。</p><p>我在另一個系統了又進行了一次測試，結果如圖3所示：</p><p><img src="https://www.linux.org/attachments/figure-03-jpg.701/" alt="Figure 03.jpg"></p><p><em>圖 3</em></p><p>這次掃描中開放的端口與上次不同。所猜的系統為 ‘Microsoft Windows 2000|XP’，實際上是 Windows XP sp3。</p><h3 id="端口嗅探結果" tabindex="-1">端口嗅探結果 <a class="header-anchor" href="#端口嗅探結果" aria-label="Permalink to “端口嗅探結果”">​</a></h3><p>讓我們來看看圖 2 所示的第一次掃描中在後台發生了什麼。</p><p>首先 NMAP 執行一次 TCP 隱秘掃描，在本次系統探測實例中以一個如圖 4 所示的數據包 2032 開始。</p><p><img src="https://www.linux.org/attachments/figure-04-jpg.702/" alt="Figure 04.jpg"></p><p><em>圖 4</em></p><p>序列生成（Sequence Generation）開始於數據包 2032/2033，第六個數據包是 2047/2048。注意每個都被髮送兩次，且每隔 100ms 發送下一個數據包。</p><p>發送的 ICMP 數據包是 2050 - 2053，2 個數據包重複一遍，實際上是 4 個數據包。</p><p>2056-2057 是 TCP 顯式擁塞通知數據包。</p><p>對 TCP 的 6 個測試是 2059、2060、2061、2063、2065、2067。</p><p>最後的 UDP 測試是 2073。</p><p>這些就是用於確定目標系統上操作系統的類型的測試。</p><p>我希望這將有助於你理解如何更新 NMAP 系統探測資料庫和執行對系統的掃描。請注意，你可以和你不在同一個網絡中的系統進行掃描，所以可以對互聯網上的任何系統進行掃描。</p><hr>`,60)),n("p",null,[s[4]||(s[4]=p("via: ",-1)),t(i,{href:"https://www.linux.org/threads/nmap-os-detection.4564/"},{default:e(()=>[...s[3]||(s[3]=[p("https://www.linux.org/threads/nmap-os-detection.4564/",-1)])]),_:1})]),n("p",null,[s[8]||(s[8]=p("作者：",-1)),t(i,{href:"https://www.linux.org/members/jarret-b.29858/"},{default:e(()=>[...s[5]||(s[5]=[p("Jarret B",-1)])]),_:1}),s[9]||(s[9]=p(" 譯者：",-1)),t(i,{href:"https://github.com/zhousiyu325"},{default:e(()=>[...s[6]||(s[6]=[p("zhousiyu325",-1)])]),_:1}),s[10]||(s[10]=p(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[7]||(s[7]=[p("wxy",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=p("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[11]||(s[11]=[p("LCTT",-1)])]),_:1}),s[14]||(s[14]=p(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[12]||(s[12]=[p("Linux中國",-1)])]),_:1}),s[15]||(s[15]=p(" 榮譽推出",-1))])])}const T=l(g,[["render",u]]);export{k as __pageData,T as default};
